window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9da97efec84e56a6"]={"versions": [{"id": "FIG-9da97efec84e56a6", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- und Timing-Diagramm zur Veranschaulichung der Ausführungsreihenfolge von <code>ExecutableEntity</code>s während eines synchronen Moduswechsels (<em>synchronous mode transition</em>) in der AUTOSAR Runtime Environment (RTE). Die Darstellung gliedert den Zustandsübergang entlang einer horizontalen Zeitachse in disjunkte Phasen zwischen altem und neuem Modus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet mehrere Klassen von ausführbaren Entitäten (<code>ExecutableEntity</code>):</p>\n<ul class=\"fig-list\"><li><strong>mode disabling dependent Executable Entities (alter Modus)</strong>: Blau markierte Ausführungseinheiten, die im Ursprungsmodus aktivierbar sind.\n</li><li><strong>OnExit Executable Entities (OEE)</strong>: Rot markierte Ausführungseinheiten, die beim Verlassen des alten Modus ausgeführt werden.\n</li><li><strong>OnTransition Executable Entities</strong>: Gelb markierte Ausführungseinheiten, die während des Übergangs ausgeführt werden.\n</li><li><strong>OnEntry Executable Entities</strong>: Grün markierte Ausführungseinheiten, die beim Eintritt in den neuen Modus ausgeführt werden.\n</li><li><strong>mode disabling dependent Executable Entities (neuer Modus)</strong>: Magenta/rosa markierte Ausführungseinheiten, die erst im Zielmodus freigegeben sind.\n</li><li><strong>Ereignis-Trigger</strong>: <code>mode switch indication</code>, dargestellt als vertikale Markierung mit Pfeil.\n</li><li><strong>Strukturierende Elemente</strong>: Durchgezogene vertikale Phasentrennlinien sowie eine horizontal verlaufende, gestrichelte graue Trennlinie zur optischen Trennung von zyklischen bzw. modusabhängigen Entitäten und Übergangsentitäten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Phase vor dem Moduswechsel</strong>: Blaue Ausführungseinheiten des alten Modus werden ausgeführt.\n</li><li><strong>Auslösen des Wechsels (<code>mode switch indication</code>)</strong>: Der Moduswechsel wird signalisiert (Pfeilmarkierung). Eine bereits gestartete blaue Entität läuft über den Indikationszeitpunkt hinaus bis zu ihrem regulären Ende weiter (gekennzeichnet durch eine feine gepunktete vertikale Hilfslinie).\n</li><li><strong>Sperrung alter Entitäten</strong>: Nach Abschluss der laufenden blauen Entität dürfen keine weiteren Entitäten des alten Modus gestartet werden.\n</li><li><strong>OnExit-Phase</strong>: Sequenzielle Ausführung der roten <code>OnExit</code>-Entitäten.\n</li><li><strong>OnTransition-Phase</strong>: Sequenzielle Ausführung der gelben <code>OnTransition</code>-Entitäten.\n</li><li><strong>OnEntry-Phase</strong>: Sequenzielle Ausführung der grünen <code>OnEntry</code>-Entitäten.\n</li><li><strong>Zielmodus aktiv</strong>: Erst nach vollständigem Abschluss der grünen <code>OnEntry</code>-Entitäten wird die Barriere zum neuen Modus überschritten und die Ausführung der neuen, magenta dargestellten <code>mode disabling dependent Executable Entities</code> freigegeben.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert die strikte Sequentialisierung und Ausführungsgarantien bei synchronen Moduswechseln der RTE:</p>\n<ul class=\"fig-list\"><li>Modusabhängige Entitäten des Zielmodus dürfen erst starten, wenn sämtliche Transitionshandler (<code>OnExit</code>, <code>OnTransition</code>, <code>OnEntry</code>) terminiert haben.\n</li><li>Bereits laufende Entitäten des alten Modus werden beim Eintreffen der Moduswechsel-Indikation nicht abgebrochen, sondern zu Ende geführt; nachfolgende Aktivierungen des alten Modus werden jedoch unmittelbar blockiert.\n</li><li>Entwickler müssen beachten, dass langlaufende Entitäten oder Übergangshandler den Abschluss des Moduswechsels und damit den Start von Funktionalitäten des neuen Modus verzögern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9e3034b06782da14", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- und Timing-Diagramm zur Veranschaulichung der Ausführungsreihenfolge von <code>ExecutableEntity</code>s während eines synchronen Moduswechsels (<em>synchronous mode transition</em>) in der AUTOSAR Runtime Environment (RTE). Die Darstellung gliedert den Zustandsübergang entlang einer horizontalen Zeitachse in disjunkte Phasen zwischen altem und neuem Modus.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet mehrere Klassen von ausführbaren Entitäten (<code>ExecutableEntity</code>):</p>\n<ul class=\"fig-list\"><li><strong>mode disabling dependent Executable Entities (alter Modus)</strong>: Blau markierte Ausführungseinheiten, die im Ursprungsmodus aktivierbar sind.\n</li><li><strong>OnExit Executable Entities (OEE)</strong>: Rot markierte Ausführungseinheiten, die beim Verlassen des alten Modus ausgeführt werden.\n</li><li><strong>OnTransition Executable Entities</strong>: Gelb markierte Ausführungseinheiten, die während des Übergangs ausgeführt werden.\n</li><li><strong>OnEntry Executable Entities</strong>: Grün markierte Ausführungseinheiten, die beim Eintritt in den neuen Modus ausgeführt werden.\n</li><li><strong>mode disabling dependent Executable Entities (neuer Modus)</strong>: Magenta/rosa markierte Ausführungseinheiten, die erst im Zielmodus freigegeben sind.\n</li><li><strong>Ereignis-Trigger</strong>: <code>mode switch indication</code>, dargestellt als vertikale Markierung mit Pfeil.\n</li><li><strong>Strukturierende Elemente</strong>: Durchgezogene vertikale Phasentrennlinien sowie eine horizontal verlaufende, gestrichelte graue Trennlinie zur optischen Trennung von zyklischen bzw. modusabhängigen Entitäten und Übergangsentitäten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Phase vor dem Moduswechsel</strong>: Blaue Ausführungseinheiten des alten Modus werden ausgeführt.\n</li><li><strong>Auslösen des Wechsels (<code>mode switch indication</code>)</strong>: Der Moduswechsel wird signalisiert (Pfeilmarkierung). Eine bereits gestartete blaue Entität läuft über den Indikationszeitpunkt hinaus bis zu ihrem regulären Ende weiter (gekennzeichnet durch eine feine gepunktete vertikale Hilfslinie).\n</li><li><strong>Sperrung alter Entitäten</strong>: Nach Abschluss der laufenden blauen Entität dürfen keine weiteren Entitäten des alten Modus gestartet werden.\n</li><li><strong>OnExit-Phase</strong>: Sequenzielle Ausführung der roten <code>OnExit</code>-Entitäten.\n</li><li><strong>OnTransition-Phase</strong>: Sequenzielle Ausführung der gelben <code>OnTransition</code>-Entitäten.\n</li><li><strong>OnEntry-Phase</strong>: Sequenzielle Ausführung der grünen <code>OnEntry</code>-Entitäten.\n</li><li><strong>Zielmodus aktiv</strong>: Erst nach vollständigem Abschluss der grünen <code>OnEntry</code>-Entitäten wird die Barriere zum neuen Modus überschritten und die Ausführung der neuen, magenta dargestellten <code>mode disabling dependent Executable Entities</code> freigegeben.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert die strikte Sequentialisierung und Ausführungsgarantien bei synchronen Moduswechseln der RTE:</p>\n<ul class=\"fig-list\"><li>Modusabhängige Entitäten des Zielmodus dürfen erst starten, wenn sämtliche Transitionshandler (<code>OnExit</code>, <code>OnTransition</code>, <code>OnEntry</code>) terminiert haben.\n</li><li>Bereits laufende Entitäten des alten Modus werden beim Eintreffen der Moduswechsel-Indikation nicht abgebrochen, sondern zu Ende geführt; nachfolgende Aktivierungen des alten Modus werden jedoch unmittelbar blockiert.\n</li><li>Entwickler müssen beachten, dass langlaufende Entitäten oder Übergangshandler den Abschluss des Moduswechsels und damit den Start von Funktionalitäten des neuen Modus verzögern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9da97efec84e56a6", "to": "FIG-9e3034b06782da14", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
